import{f as e,h as t,j as n,n as r}from"./chunks/shared.rYHlazZf.js";var i=JSON.parse(`{"title":"CLI コマンドリファレンス","description":"","frontmatter":{"title":"CLI コマンドリファレンス","docId":"developer.cli","translationKey":"developer.cli","locale":"ja","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"6bb485d6e8067cb1639fb20821c45b79941245692f0b6c7525f2b3bee930048b","translationRevision":"99242db6ea6c989f5eb459b10fb84a98a8bb5499e2e2d6bd73d7b00d32be8b4d","order":75},"headers":[],"relativePath":"ja/developer/cli.md","filePath":"ja/developer/cli.md","lastUpdated":1795735295000}`),a={name:`ja/developer/cli.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="cli-command-reference" tabindex="-1">CLI コマンドリファレンス <a class="header-anchor" href="#cli-command-reference" aria-label="Permalink to “CLI コマンドリファレンス”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目的と前提条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “目的と前提条件”">​</a></h2><p>Rust のソースを読んだり人間向けのヘルプ出力を解析したりせずに、すべての <code>tiktools</code> コマンド形式を発見します。一致する <code>tiktools</code> バイナリがビルドされている必要があります。このリファレンスはオフラインで、実行中の host を必要としません。正規のソースは <code>crates/tiktools-cli/src/commands/spec.rs</code> のコマンド仕様レジストリです。各ドメインモジュールはパーサーがエラーで報告する使用法文字列を所有しているため、このリファレンスはパーサーが受け入れるものから逸脱しません。</p><h2 id="inspect-help-offline" tabindex="-1">オフラインでヘルプを検査 <a class="header-anchor" href="#inspect-help-offline" aria-label="Permalink to “オフラインでヘルプを検査”">​</a></h2><p>人間向けヘルプはドメインごとに動詞をグループ化します。フィルターを指定すると1つのドメインセクションが表示されます。<code>--json</code> 形式は、すべてのエージェントが優先すべき機械可読レジストリを出力します。動詞ごとの使用法、要約、破壊的マーカーに加え、グローバルな CLI 規約が含まれ、トップレベルの <code>schema</code> フィールドでバージョン管理されています。</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> help</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> help</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plugin</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> help</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span></code></pre></div><p>使用法エラーはページ全体ではなく、関連する形式とヒントのみを出力するため、タイプミスでターミナルがスクロールすることはありません。終了コード 2 は常に使用法エラーを意味します。host 解決、出力、シークレット秘匿のルールについては、規約のフッターを参照してください。</p><h2 id="generated-command-reference" tabindex="-1">生成されたコマンドリファレンス <a class="header-anchor" href="#generated-command-reference" aria-label="Permalink to “生成されたコマンドリファレンス”">​</a></h2><p><code>docs/contracts/cli-help.json</code> にチェックインされた CLI ヘルプスナップショットから生成されます。バイナリが権威であり続けます。使用法行はパーサーの構文であり、すべてのロケールで英語のままです。要約と規約は CLI 自身の翻訳カタログから来るため、このリファレンスは <code>tiktools help</code> が同じ言語で出力する内容から逸脱しません。破壊的とマークされた動詞は状態を変更または破棄します。スクリプトは実行前に確認すべきです。</p><p><code>tiktools [--json] [--standalone] &lt;command&gt; [args]</code></p><h3 id="tiktools-plugin-—-プラグインのインストールと管理" tabindex="-1"><code>tiktools plugin</code> — プラグインのインストールと管理 <a class="header-anchor" href="#tiktools-plugin-—-プラグインのインストールと管理" aria-label="Permalink to “tiktools plugin — プラグインのインストールと管理”">​</a></h3><table tabindex="0"><thead><tr><th>コマンド</th><th>概要</th></tr></thead><tbody><tr><td><code>tiktools plugin list</code></td><td>インストール済みプラグインを一覧表示</td></tr><tr><td><code>tiktools plugin get &lt;id&gt;</code></td><td>プラグインを1つ読み取る</td></tr><tr><td><code>tiktools plugin install &lt;file.plugin&gt; [--replace] &amp;#124; plugin install &lt;id[@version]&amp;#124;url&gt; [--yes] [--no-wait] [--allow-unsigned]</code></td><td>ファイル、id@version または url からインストール</td></tr><tr><td><code>tiktools plugin uninstall &lt;id&gt; [--purge]</code></td><td>プラグインをアンインストール <strong>破壊的</strong></td></tr><tr><td><code>tiktools plugin search &lt;query&gt; [--category c] [--page N]</code></td><td>レジストリでパッケージを検索</td></tr><tr><td><code>tiktools plugin inspect &lt;spec&gt;</code></td><td>インストール前にパッケージ仕様を検査</td></tr><tr><td><code>tiktools plugin outdated</code></td><td>更新可能なインストール済みプラグインを一覧表示</td></tr><tr><td><code>tiktools plugin update &lt;id&gt; [--version v] [--yes] [--no-wait]</code></td><td>プラグインを1つ更新</td></tr><tr><td><code>tiktools plugin update --all [--yes] [--no-wait]</code></td><td>すべての古いプラグインを更新</td></tr><tr><td><code>tiktools plugin rollback &lt;id&gt; [version] [--no-wait]</code></td><td>以前のバージョンにロールバック <strong>破壊的</strong></td></tr><tr><td><code>tiktools plugin versions &lt;id&gt;</code></td><td>プラグインの利用可能なバージョンを一覧表示</td></tr><tr><td><code>tiktools plugin pin &lt;id&gt;</code></td><td>プラグインを現在のバージョンにピン留め</td></tr><tr><td><code>tiktools plugin unpin &lt;id&gt;</code></td><td>バージョンのピン留めを解除</td></tr><tr><td><code>tiktools plugin policy &lt;id&gt; [--channel stable&amp;#124;beta] [--auto off&amp;#124;notify&amp;#124;patch&amp;#124;minor]</code></td><td>チャンネルと自動更新ポリシーを設定</td></tr><tr><td><code>tiktools plugin jobs</code></td><td>パッケージジョブを一覧表示</td></tr><tr><td><code>tiktools plugin job &lt;job-id&gt;</code></td><td>パッケージジョブを1つ検査</td></tr><tr><td><code>tiktools plugin cancel &lt;job-id&gt;</code></td><td>実行中のパッケージジョブをキャンセル <strong>破壊的</strong></td></tr><tr><td><code>tiktools plugin enable &lt;id&gt;</code></td><td>プラグインを有効化</td></tr><tr><td><code>tiktools plugin disable &lt;id&gt;</code></td><td>プラグインを無効化</td></tr><tr><td><code>tiktools plugin start &lt;id&gt;</code></td><td>プラグインを開始</td></tr><tr><td><code>tiktools plugin stop &lt;id&gt;</code></td><td>プラグインを停止 <strong>破壊的</strong></td></tr><tr><td><code>tiktools plugin settings get &lt;id&gt;</code></td><td>プラグイン設定を読み取る</td></tr><tr><td><code>tiktools plugin settings set &lt;id&gt; k=v...</code></td><td>プラグイン設定を書き込む</td></tr><tr><td><code>tiktools plugin settings reset &lt;id&gt;</code></td><td>プラグイン設定をリセット <strong>破壊的</strong></td></tr><tr><td><code>tiktools plugin health &lt;id&gt;</code></td><td>プラグインのヘルスチェック</td></tr><tr><td><code>tiktools plugin options &lt;action-type/field&gt;</code></td><td>アクションタイプまたはフィールドのオプション</td></tr><tr><td><code>tiktools plugin action &lt;type&gt; [--config json] [--live]</code></td><td>プラグインアクションを実行</td></tr><tr><td><code>tiktools plugin commands</code></td><td>インストール済みプラグインが提供するコマンドを一覧表示</td></tr><tr><td><code>tiktools plugin help [id]</code></td><td>提供されたコマンドを1つ説明</td></tr><tr><td><code>tiktools plugin &lt;id&gt; &lt;command&gt; [--params json] [--live]</code></td><td>プラグイン提供コマンドを呼び出す</td></tr></tbody></table><h3 id="tiktools-cloud-—-クラウドアカウントとポータブルバックアップ-復元-tiktools-cloud-origin-で上書き" tabindex="-1"><code>tiktools cloud</code> — クラウドアカウントとポータブルバックアップ/復元（TIKTOOLS_CLOUD_ORIGIN で上書き） <a class="header-anchor" href="#tiktools-cloud-—-クラウドアカウントとポータブルバックアップ-復元-tiktools-cloud-origin-で上書き" aria-label="Permalink to “tiktools cloud — クラウドアカウントとポータブルバックアップ/復元（TIKTOOLS_CLOUD_ORIGIN で上書き）”">​</a></h3><table tabindex="0"><thead><tr><th>コマンド</th><th>概要</th></tr></thead><tbody><tr><td><code>tiktools cloud status</code></td><td>クラウドアカウントの状態</td></tr><tr><td><code>tiktools cloud login</code></td><td>システムブラウザでサインイン</td></tr><tr><td><code>tiktools cloud logout</code></td><td>サインアウト <strong>破壊的</strong></td></tr><tr><td><code>tiktools cloud restore</code></td><td>クラウドセッションを復元</td></tr><tr><td><code>tiktools cloud backup create [--out FILE]</code></td><td>ポータブルバックアップアーカイブを書き出す</td></tr><tr><td><code>tiktools cloud backup preview &lt;file&gt;</code></td><td>バックアップアーカイブを検査</td></tr><tr><td><code>tiktools cloud backup restore &lt;file&gt; [--yes]</code></td><td>バックアップアーカイブを復元 <strong>破壊的</strong></td></tr></tbody></table><h3 id="tiktools-publisher-—-クラウドパブリッシャーフロー-サインインが必要" tabindex="-1"><code>tiktools publisher</code> — クラウドパブリッシャーフロー（サインインが必要） <a class="header-anchor" href="#tiktools-publisher-—-クラウドパブリッシャーフロー-サインインが必要" aria-label="Permalink to “tiktools publisher — クラウドパブリッシャーフロー（サインインが必要）”">​</a></h3><table tabindex="0"><thead><tr><th>コマンド</th><th>概要</th></tr></thead><tbody><tr><td><code>tiktools publisher list</code></td><td>パブリッシャー名前空間を一覧表示</td></tr><tr><td><code>tiktools publisher create &lt;namespace&gt;</code></td><td>パブリッシャー名前空間を作成</td></tr><tr><td><code>tiktools publisher delete &lt;namespace-or-publisher-id&gt;</code></td><td>名前空間またはパブリッシャーを削除 <strong>破壊的</strong></td></tr><tr><td><code>tiktools publisher keys &lt;publisher-id&gt;</code></td><td>パブリッシャーの署名キーを一覧表示</td></tr><tr><td><code>tiktools publisher enroll &lt;publisher-id&gt; [--key-id &lt;id&gt;]</code></td><td>パブリッシャーキーを登録；バックエンドのパスワードを stdin から読み取る</td></tr><tr><td><code>tiktools publisher upload &lt;publisher-id&gt; &lt;path&gt;</code></td><td>プラグインパッケージをアップロード</td></tr><tr><td><code>tiktools publisher submit &lt;upload-id&gt; &lt;publisher-key-id&gt; &lt;plugin-id&gt; &lt;version&gt; [--target any]</code></td><td>アップロードをレビューに提出</td></tr><tr><td><code>tiktools publisher release &lt;release-id&gt;</code></td><td>リリースを作成</td></tr><tr><td><code>tiktools publisher publish &lt;release-id&gt;</code></td><td>リリースを公開</td></tr></tbody></table><h3 id="tiktools-registry-—-パッケージレジストリとクラウドカタログ" tabindex="-1"><code>tiktools registry</code> — パッケージレジストリとクラウドカタログ <a class="header-anchor" href="#tiktools-registry-—-パッケージレジストリとクラウドカタログ" aria-label="Permalink to “tiktools registry — パッケージレジストリとクラウドカタログ”">​</a></h3><table tabindex="0"><thead><tr><th>コマンド</th><th>概要</th></tr></thead><tbody><tr><td><code>tiktools registry list</code></td><td>設定済みレジストリを一覧表示</td></tr><tr><td><code>tiktools registry refresh</code></td><td>レジストリメタデータを更新</td></tr><tr><td><code>tiktools registry package &lt;id&gt;</code></td><td>レジストリパッケージを1つ表示</td></tr><tr><td><code>tiktools registry cloud-catalog [--query q] [--after cursor] [--generation value] [--target name]</code></td><td>クラウドカタログを検索</td></tr><tr><td><code>tiktools registry cloud-summaries [--query q] [--cursor value] [--generation value] [--target name]</code></td><td>クラウドカタログのサマリーページ</td></tr><tr><td><code>tiktools registry cloud-versions &lt;id&gt; [--target name] [--generation value] [--cursor value]</code></td><td>クラウドカタログパッケージのバージョン</td></tr><tr><td><code>tiktools registry cloud-pagination</code></td><td>クラウドカタログのページネーション機能</td></tr><tr><td><code>tiktools registry defaults</code></td><td>デフォルトのレジストリ設定</td></tr></tbody></table><h3 id="tiktools-processor-—-イベントプロセッサー" tabindex="-1"><code>tiktools processor</code> — イベントプロセッサー <a class="header-anchor" href="#tiktools-processor-—-イベントプロセッサー" aria-label="Permalink to “tiktools processor — イベントプロセッサー”">​</a></h3><table tabindex="0"><thead><tr><th>コマンド</th><th>概要</th></tr></thead><tbody><tr><td><code>tiktools processor list</code></td><td>プロセッサーを一覧表示</td></tr><tr><td><code>tiktools processor status</code></td><td>プロセッサーパイプラインの状態</td></tr><tr><td><code>tiktools processor test &lt;plugin-id&gt; &lt;processor-id&gt; [event-json]</code></td><td>サンプルイベントに対してプロセッサーを1つ実行</td></tr></tbody></table><h3 id="tiktools-live-—-tiktok-live-接続" tabindex="-1"><code>tiktools live</code> — TikTok LIVE 接続 <a class="header-anchor" href="#tiktools-live-—-tiktok-live-接続" aria-label="Permalink to “tiktools live — TikTok LIVE 接続”">​</a></h3><table tabindex="0"><thead><tr><th>コマンド</th><th>概要</th></tr></thead><tbody><tr><td><code>tiktools live connect --unique-id &lt;id&gt; --session-cookie &lt;cookie&gt; [--room-id &lt;id&gt;]</code></td><td>ライブルームに接続</td></tr><tr><td><code>tiktools live pick --session-cookie &lt;cookie&gt;</code></td><td>ライブルームを対話的に選択</td></tr><tr><td><code>tiktools live channels [--keyword text] [--offset N] [--limit N] [--session-cookie &lt;cookie&gt;]</code></td><td>ライブチャンネルを発見；セッションなしで動作</td></tr><tr><td><code>tiktools live disconnect</code></td><td>現在のルームから切断 <strong>破壊的</strong></td></tr><tr><td><code>tiktools live status</code></td><td>現在の接続状態</td></tr></tbody></table><h3 id="tiktools-points-—-視聴者ロイヤルティポイント" tabindex="-1"><code>tiktools points</code> — 視聴者ロイヤルティポイント <a class="header-anchor" href="#tiktools-points-—-視聴者ロイヤルティポイント" aria-label="Permalink to “tiktools points — 視聴者ロイヤルティポイント”">​</a></h3><table tabindex="0"><thead><tr><th>コマンド</th><th>概要</th></tr></thead><tbody><tr><td><code>tiktools points config get</code></td><td>ポイント設定を読み取る</td></tr><tr><td><code>tiktools points config set k=v...</code></td><td>ポイント設定を更新</td></tr><tr><td><code>tiktools points viewer get &lt;id&gt;</code></td><td>視聴者1人の残高を読み取る</td></tr><tr><td><code>tiktools points adjust &lt;id&gt; &lt;delta&gt;</code></td><td>視聴者のポイントを加算または減算</td></tr><tr><td><code>tiktools points leaderboard [--limit N]</code></td><td>残高上位の視聴者</td></tr><tr><td><code>tiktools points reset [id]</code></td><td>視聴者1人またはすべての残高をリセット <strong>破壊的</strong></td></tr></tbody></table><h3 id="tiktools-ranking-—-視聴者ランキングの定義と状態" tabindex="-1"><code>tiktools ranking</code> — 視聴者ランキングの定義と状態 <a class="header-anchor" href="#tiktools-ranking-—-視聴者ランキングの定義と状態" aria-label="Permalink to “tiktools ranking — 視聴者ランキングの定義と状態”">​</a></h3><table tabindex="0"><thead><tr><th>コマンド</th><th>概要</th></tr></thead><tbody><tr><td><code>tiktools ranking list</code></td><td>ランキング定義を一覧表示</td></tr><tr><td><code>tiktools ranking metrics</code></td><td>ランキング定義で利用可能なメトリクス</td></tr><tr><td><code>tiktools ranking create --record &lt;json&amp;#124;@file&gt;</code></td><td>ランキング定義を作成</td></tr><tr><td><code>tiktools ranking update --record &lt;json&amp;#124;@file&gt;</code></td><td>ランキング定義を更新</td></tr><tr><td><code>tiktools ranking get &lt;id&gt;</code></td><td>ランキングを1つ読み取る</td></tr><tr><td><code>tiktools ranking snapshot &lt;id&gt;</code></td><td>ランキングの現在の順位</td></tr><tr><td><code>tiktools ranking delete &lt;id&gt;</code></td><td>ランキングを削除 <strong>破壊的</strong></td></tr><tr><td><code>tiktools ranking reset &lt;id&gt;</code></td><td>蓄積状態をリセット <strong>破壊的</strong></td></tr><tr><td><code>tiktools ranking pause &lt;id&gt;</code></td><td>蓄積を一時停止</td></tr><tr><td><code>tiktools ranking resume &lt;id&gt;</code></td><td>蓄積を再開</td></tr><tr><td><code>tiktools ranking contribute --record &lt;json&amp;#124;@file&gt;</code></td><td>外部の貢献を追加</td></tr></tbody></table><h3 id="tiktools-competition-—-時間制限付き視聴者コンペティション" tabindex="-1"><code>tiktools competition</code> — 時間制限付き視聴者コンペティション <a class="header-anchor" href="#tiktools-competition-—-時間制限付き視聴者コンペティション" aria-label="Permalink to “tiktools competition — 時間制限付き視聴者コンペティション”">​</a></h3><table tabindex="0"><thead><tr><th>コマンド</th><th>概要</th></tr></thead><tbody><tr><td><code>tiktools competition list</code></td><td>コンペティションを一覧表示</td></tr><tr><td><code>tiktools competition get &lt;id&gt;</code></td><td>コンペティションを1つ読み取る</td></tr><tr><td><code>tiktools competition create --record &lt;json&amp;#124;@file&gt;</code></td><td>コンペティションを作成</td></tr><tr><td><code>tiktools competition update --record &lt;json&amp;#124;@file&gt;</code></td><td>コンペティションを更新</td></tr><tr><td><code>tiktools competition delete &lt;id&gt;</code></td><td>コンペティションを削除 <strong>破壊的</strong></td></tr><tr><td><code>tiktools competition state &lt;id&gt;</code></td><td>現在のコンペティション状態</td></tr><tr><td><code>tiktools competition results &lt;id&gt;</code></td><td>最終または中間結果</td></tr><tr><td><code>tiktools competition action --record &lt;json&amp;#124;@file&gt;</code></td><td>コンペティションアクションを記録</td></tr><tr><td><code>tiktools competition mark-action-uncertain --record &lt;json&amp;#124;@file&gt;</code></td><td>アクションを不確実としてフラグ</td></tr><tr><td><code>tiktools competition resolve-action --record &lt;json&amp;#124;@file&gt;</code></td><td>不確実なアクションを解決</td></tr><tr><td><code>tiktools competition start &lt;id&gt;</code></td><td>コンペティションを開始</td></tr><tr><td><code>tiktools competition finish &lt;id&gt;</code></td><td>コンペティションを終了 <strong>破壊的</strong></td></tr><tr><td><code>tiktools competition candidates &lt;id&gt;</code></td><td>勝者候補</td></tr><tr><td><code>tiktools competition select-winner --record &lt;json&amp;#124;@file&gt;</code></td><td>勝者を選択</td></tr><tr><td><code>tiktools competition pause &lt;id&gt;</code></td><td>コンペティションを一時停止</td></tr><tr><td><code>tiktools competition resume &lt;id&gt;</code></td><td>コンペティションを再開</td></tr><tr><td><code>tiktools competition cancel &lt;id&gt;</code></td><td>コンペティションをキャンセル <strong>破壊的</strong></td></tr></tbody></table><h3 id="tiktools-automation-—-イベントとアクションの自動化ルール" tabindex="-1"><code>tiktools automation</code> — イベントとアクションの自動化ルール <a class="header-anchor" href="#tiktools-automation-—-イベントとアクションの自動化ルール" aria-label="Permalink to “tiktools automation — イベントとアクションの自動化ルール”">​</a></h3><table tabindex="0"><thead><tr><th>コマンド</th><th>概要</th></tr></thead><tbody><tr><td><code>tiktools automation list [--kind event&amp;#124;action&amp;#124;all]</code></td><td>自動化ルールを一覧表示</td></tr><tr><td><code>tiktools automation context [--event-type t]</code></td><td>ルールで利用可能なテンプレートコンテキスト</td></tr><tr><td><code>tiktools automation get &lt;id&gt; [--kind event&amp;#124;action]</code></td><td>ルールを1つ読み取る</td></tr><tr><td><code>tiktools automation create --record json [--kind event&amp;#124;action]</code></td><td>ルールを作成</td></tr><tr><td><code>tiktools automation update &lt;id&gt; --record json [--kind event&amp;#124;action]</code></td><td>ルールを更新</td></tr><tr><td><code>tiktools automation delete &lt;id&gt; [--kind event&amp;#124;action]</code></td><td>ルールを削除 <strong>破壊的</strong></td></tr><tr><td><code>tiktools automation enable &lt;id&gt; [--kind event&amp;#124;action]</code></td><td>ルールを有効化</td></tr><tr><td><code>tiktools automation disable &lt;id&gt; [--kind event&amp;#124;action]</code></td><td>ルールを無効化</td></tr><tr><td><code>tiktools automation test (--id &lt;id&gt; &amp;#124; --record json) [--kind event&amp;#124;action] [--trigger t] [--event json]</code></td><td>サンプルイベントに対してルールをドライラン</td></tr><tr><td><code>tiktools automation fire --trigger &lt;type&gt; [--event json] [--record json]</code></td><td>トリガーを手動で発火</td></tr><tr><td><code>tiktools automation moderation-penalty --points &lt;delta&gt;</code></td><td>ポイントでモデレーションペナルティを適用</td></tr></tbody></table><h3 id="tiktools-globals-—-プラグイン間で共有されるキー-バリューグローバル" tabindex="-1"><code>tiktools globals</code> — プラグイン間で共有されるキー/バリューグローバル <a class="header-anchor" href="#tiktools-globals-—-プラグイン間で共有されるキー-バリューグローバル" aria-label="Permalink to “tiktools globals — プラグイン間で共有されるキー/バリューグローバル”">​</a></h3><table tabindex="0"><thead><tr><th>コマンド</th><th>概要</th></tr></thead><tbody><tr><td><code>tiktools globals list</code></td><td>すべてのグローバルキーを一覧表示</td></tr><tr><td><code>tiktools globals get &lt;key&gt;</code></td><td>グローバルを1つ読み取る</td></tr><tr><td><code>tiktools globals set &lt;key&gt; &lt;value&gt;</code></td><td>グローバルを1つ書き込む</td></tr><tr><td><code>tiktools globals delete &lt;key&gt;</code></td><td>グローバルを1つ削除 <strong>破壊的</strong></td></tr></tbody></table><h3 id="tiktools-workflow-—-ビジュアルワークフローグラフ" tabindex="-1"><code>tiktools workflow</code> — ビジュアルワークフローグラフ <a class="header-anchor" href="#tiktools-workflow-—-ビジュアルワークフローグラフ" aria-label="Permalink to “tiktools workflow — ビジュアルワークフローグラフ”">​</a></h3><table tabindex="0"><thead><tr><th>コマンド</th><th>概要</th></tr></thead><tbody><tr><td><code>tiktools workflow list</code></td><td>保存されたワークフローグラフを一覧表示</td></tr><tr><td><code>tiktools workflow get &lt;id&gt;</code></td><td>グラフを1つ読み取る</td></tr><tr><td><code>tiktools workflow save --record json</code></td><td>グラフを作成または置換</td></tr><tr><td><code>tiktools workflow delete &lt;id&gt;</code></td><td>グラフを削除 <strong>破壊的</strong></td></tr><tr><td><code>tiktools workflow enable &lt;id&gt;</code></td><td>グラフを有効化</td></tr><tr><td><code>tiktools workflow disable &lt;id&gt;</code></td><td>グラフを無効化</td></tr></tbody></table><h3 id="tiktools-media-—-メディアファイルの検証と再生" tabindex="-1"><code>tiktools media</code> — メディアファイルの検証と再生 <a class="header-anchor" href="#tiktools-media-—-メディアファイルの検証と再生" aria-label="Permalink to “tiktools media — メディアファイルの検証と再生”">​</a></h3><table tabindex="0"><thead><tr><th>コマンド</th><th>概要</th></tr></thead><tbody><tr><td><code>tiktools media validate &lt;path&gt; [--kind audio&amp;#124;video&amp;#124;image&amp;#124;other]</code></td><td>アクションで使用する前にメディアファイルを検証</td></tr></tbody></table><h3 id="tiktools-system-—-ホスト情報と診断" tabindex="-1"><code>tiktools system</code> — ホスト情報と診断 <a class="header-anchor" href="#tiktools-system-—-ホスト情報と診断" aria-label="Permalink to “tiktools system — ホスト情報と診断”">​</a></h3><table tabindex="0"><thead><tr><th>コマンド</th><th>概要</th></tr></thead><tbody><tr><td><code>tiktools system info</code></td><td>ホストバージョンとランタイム情報</td></tr><tr><td><code>tiktools system health</code></td><td>コンポーネントヘルスレポート</td></tr><tr><td><code>tiktools system snapshot</code></td><td>デバッグ用の完全な状態スナップショット</td></tr><tr><td><code>tiktools system doctor</code></td><td>一般的なセットアップ問題を診断</td></tr><tr><td><code>tiktools system request-input-access</code></td><td>デスクトップユーザーに入力アクセスを要求</td></tr><tr><td><code>tiktools system shutdown</code></td><td>実行中のホストをシャットダウン <strong>破壊的</strong></td></tr></tbody></table><h3 id="tiktools-template-—-再利用可能な自動化テンプレートとプロファイル" tabindex="-1"><code>tiktools template</code> — 再利用可能な自動化テンプレートとプロファイル <a class="header-anchor" href="#tiktools-template-—-再利用可能な自動化テンプレートとプロファイル" aria-label="Permalink to “tiktools template — 再利用可能な自動化テンプレートとプロファイル”">​</a></h3><table tabindex="0"><thead><tr><th>コマンド</th><th>概要</th></tr></thead><tbody><tr><td><code>tiktools template import &lt;file&gt; [--param k=v]... [--event-name n] [--action-name n] [--dry-run] [--no-save] [--disabled]</code></td><td>テンプレートを自動化ルールとしてインポート</td></tr><tr><td><code>tiktools template export --event &lt;id&gt; --out &lt;file&gt; [--title t] [--id template-id]</code></td><td>イベントルールをテンプレートとしてエクスポート</td></tr><tr><td><code>tiktools template list</code></td><td>ギャラリーのテンプレートを一覧表示</td></tr><tr><td><code>tiktools template delete &lt;template-id&gt;</code></td><td>テンプレートを削除 <strong>破壊的</strong></td></tr><tr><td><code>tiktools template profile-import &lt;file&gt; [--param k=v]... [--dry-run] [--no-save] [--disabled]</code></td><td>自動化プロファイル全体をインポート</td></tr><tr><td><code>tiktools template profile-export --out &lt;file&gt; [--name n]</code></td><td>自動化プロファイルをエクスポート</td></tr></tbody></table><h3 id="tiktools-api-—-ホストメソッド上のエージェント指向の汎用コントロールサーフェス" tabindex="-1"><code>tiktools api</code> — ホストメソッド上のエージェント指向の汎用コントロールサーフェス <a class="header-anchor" href="#tiktools-api-—-ホストメソッド上のエージェント指向の汎用コントロールサーフェス" aria-label="Permalink to “tiktools api — ホストメソッド上のエージェント指向の汎用コントロールサーフェス”">​</a></h3><table tabindex="0"><thead><tr><th>コマンド</th><th>概要</th></tr></thead><tbody><tr><td><code>tiktools api discover [--format json&amp;#124;human]</code></td><td>ホストレジストリからすべてのメソッドをライブで一覧表示</td></tr><tr><td><code>tiktools api schema &lt;method&gt; [--format json&amp;#124;human]</code></td><td>メソッド1つの説明、フラグ、スキーマ</td></tr><tr><td><code>tiktools api call &lt;method&gt; [params-json] [--timeout SEC] [--dry-run] [--confirm] [--redact&amp;#124;--secrets-visible] [--explain] [--format json&amp;#124;human] [--expected-revision N] [--command-id ID --host-instance-id ID] [--include-meta]</code></td><td>メソッドを検証して実行；破壊的メソッドには --confirm が必要</td></tr><tr><td><code>tiktools api events [--topics t,...] [--timeout SEC] [--max-events N]</code></td><td>NDJSON ドメインイベントをストリーム</td></tr><tr><td><code>tiktools api event get &lt;name&gt; [--type kind]... [--author text] [--limit N]</code></td><td>有界フィードジャーナルを検索</td></tr><tr><td><code>tiktools api verify [--coverage&amp;#124;--smoke] [--sandbox] [--timeout SEC]</code></td><td>ホストに対してコントロールサーフェスを検証</td></tr></tbody></table><h3 id="tiktools-host-—-ヘッドレスホストランタイムと生の-rpc-パススルー" tabindex="-1"><code>tiktools host</code> — ヘッドレスホストランタイムと生の rpc パススルー <a class="header-anchor" href="#tiktools-host-—-ヘッドレスホストランタイムと生の-rpc-パススルー" aria-label="Permalink to “tiktools host — ヘッドレスホストランタイムと生の rpc パススルー”">​</a></h3><table tabindex="0"><thead><tr><th>コマンド</th><th>概要</th></tr></thead><tbody><tr><td><code>tiktools host --stdio [--events]</code></td><td>stdio 上のヘッドレスホスト；--events でイベントをストリーム</td></tr><tr><td><code>tiktools host --ipc</code></td><td>ローカル IPC 上のヘッドレスホスト；ホスト実行中は拒否</td></tr><tr><td><code>tiktools rpc &lt;method&gt; [params-json] &amp;#124; rpc --stdio [--events]</code></td><td>任意のホストメソッドへの型なしパススルー</td></tr><tr><td><code>tiktools rpc --stdio [--events]</code></td><td>stdio 上の NDJSON リクエスト/レスポンスループ</td></tr></tbody></table><h3 id="tiktools-web-—-ローカルブラウザアダプター-local-web-フィーチャーが必要" tabindex="-1"><code>tiktools web</code> — ローカルブラウザアダプター（local-web フィーチャーが必要） <a class="header-anchor" href="#tiktools-web-—-ローカルブラウザアダプター-local-web-フィーチャーが必要" aria-label="Permalink to “tiktools web — ローカルブラウザアダプター（local-web フィーチャーが必要）”">​</a></h3><table tabindex="0"><thead><tr><th>コマンド</th><th>概要</th></tr></thead><tbody><tr><td><code>tiktools web --assets &lt;directory&gt; [--port N] [--join-origin URL] [--multi-session]</code></td><td>ローカルブラウザアダプターを提供；host --ipc が実行中である必要がある</td></tr><tr><td><code>tiktools web --print-code [--port N]</code></td><td>再起動せずにアクティブなペアリングコードを印刷</td></tr><tr><td><code>tiktools web --reset-session [--port N]</code></td><td>すべてのペアリング済みブラウザを取り消し、新しいコードを印刷 <strong>破壊的</strong></td></tr></tbody></table><h3 id="規約" tabindex="-1">規約 <a class="header-anchor" href="#規約" aria-label="Permalink to “規約”">​</a></h3><ul><li><strong>ホスト解決</strong>: コマンドはローカル IPC 経由で実行中のホストに対して実行されます。ホストが実行されていない場合、2 つ目のランタイムを起動する代わりに host_unavailable で失敗します。軽量プローブとして <code>tiktools --json system info</code> を使用してください：終了コード 0 はホストが応答したことを、3 は IPC ホストが利用不可であることを意味します。--standalone はコマンドを分離されたプロセス内ランタイムに対して実行します。</li><li><strong>出力</strong>: stdout は結果を運び、診断は stderr に送られます。--json は生の結果オブジェクトを出力します。指定がない場合、リストは項目ごとに 1 行で出力します。json 値は @path でファイルから読み取れます。人間向けヘルプは表示ロケールに従います：TIKTOOLS_LANG は LC_ALL/LC_MESSAGES/LANG チェーンを上書きし、マシン出力はロケールに依存しません。</li><li><strong>終了コード</strong>: 0 成功、1 操作エラー、2 使用法エラー、3 転送失敗。</li><li><strong>シークレット</strong>: live connect/pick はセッション cookie を --session-cookie または環境変数 TIKTOOLS_SESSION_COOKIE から読み取ります（フラグが優先）。値が診断に表示されることはありません。api call は --secrets-visible が渡されない限り出力からシークレットを伏せ、--confirm なしでは破壊的メソッドを拒否します。</li></ul><h2 id="operational-details" tabindex="-1">運用上の詳細 <a class="header-anchor" href="#operational-details" aria-label="Permalink to “運用上の詳細”">​</a></h2><p>スナップショットは <code>--features local-web</code> でビルドされたバイナリから再生成され、フィーチャーゲートされたドメイン（cloud、publisher、web）が完全であることを保証します。<code>docs check</code> のプロベナンスチェックはすべての Rust ソースのハッシュを比較するため、コマンド仕様の変更はコントラクトが再生成されるまでビルドを失敗させます。通常のドキュメントビルドで Cargo が実行されることはありません。</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/scripts/regenerate-control.ts</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/scripts/generate-references.ts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/scripts/cli-coverage.ts</span></span></code></pre></div><p>コマンドパーサーまたは仕様を変更した後に再生成を実行し、変更の一部としてフラグメントの diff を確認してください。<code>help --json</code> を消費するエージェントは、スキーマバージョン 1 を加法的に安定しているものとして扱うべきです。新しい動詞、ドメイン、フィールドが予告なく現れることがありますが、既存のキーはその意味を保持します。</p>`,52)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};